package com.acme.core.common.core;

import java.util.Map;
import java.util.Optional;

/**
 * Stable request context (generated by engineering-platform 0.1.0).
 *
 * Holds minimal, safe request metadata: requestId / correlationId, an abstract
 * current-user reference, and optional safe metadata.
 *
 * RequestContext is NOT an authentication implementation: it does not depend on
 * Spring Security, Sa-Token, or any servlet-specific security object.
 */
public final class RequestContext {

    /** Minimal safe request context payload. */
    public record Context(String requestId, String correlationId, String currentUserId,
                          String currentDepartmentId, Map<String, String> metadata) {

        public static Context of(String requestId, String correlationId) {
            return new Context(requestId, correlationId, null, null, Map.of());
        }

        public static Context of(String requestId, String correlationId, String currentUserId) {
            return new Context(requestId, correlationId, currentUserId, null, Map.of());
        }

        public static Context of(String requestId, String correlationId, String currentUserId,
                                 String currentDepartmentId) {
            return new Context(requestId, correlationId, currentUserId, currentDepartmentId, Map.of());
        }
    }

    private static final ThreadLocal<Context> HOLDER = new ThreadLocal<>();

    private RequestContext() {
    }

    public static void set(Context context) {
        HOLDER.set(context);
    }

    public static void clear() {
        HOLDER.remove();
    }

    public static Optional<Context> get() {
        return Optional.ofNullable(HOLDER.get());
    }

    public static Optional<String> requestId() {
        Context c = HOLDER.get();
        return c == null ? Optional.empty() : Optional.ofNullable(c.requestId());
    }

    public static Optional<String> correlationId() {
        Context c = HOLDER.get();
        return c == null ? Optional.empty() : Optional.ofNullable(c.correlationId());
    }

    /** Abstract current-user reference; not bound to any authentication framework. */
    public static Optional<String> currentUserId() {
        Context c = HOLDER.get();
        return c == null ? Optional.empty() : Optional.ofNullable(c.currentUserId());
    }

    /** Abstract current-department reference (set by the auth chain when known). */
    public static Optional<String> currentDepartmentId() {
        Context c = HOLDER.get();
        return c == null ? Optional.empty() : Optional.ofNullable(c.currentDepartmentId());
    }

    public static Map<String, String> metadata() {
        Context c = HOLDER.get();
        return c == null ? Map.of() : c.metadata() == null ? Map.of() : c.metadata();
    }
}
